    private static readonly IReadOnlyDictionary<string, IReadOnlyDictionary<string, string>> Languages =
        new Dictionary<string, IReadOnlyDictionary<string, string>>(StringComparer.OrdinalIgnoreCase)
        {
            ["en"] = English, ["fr"] = French, ["es"] = Spanish, ["de"] = German, ["it"] = Italian, ["pt"] = Portuguese
        };

    public static string NormalizeLanguage(string? languageCode)
    {
        var code = languageCode?.Trim().ToLowerInvariant();
        return code switch
        {
            "fr" or "français" or "french" => "fr",
            "es" or "español" or "spanish" => "es",
            "de" or "deutsch" or "german" => "de",
            "it" or "italiano" or "italian" => "it",
            "pt" or "português" or "portuguese" => "pt",
            _ => "en"
        };
    }

    public static string Get(string? languageCode, string key)
    {
        var dictionary = Languages[NormalizeLanguage(languageCode)];
        return dictionary.TryGetValue(key, out var value)
            ? value
            : English.TryGetValue(key, out var fallback) ? fallback : key;
    }

    public static void ApplyCulture(string? languageCode)
    {
        var cultureName = NormalizeLanguage(languageCode) switch
        {
            "fr" => "fr-FR", "es" => "es-ES", "de" => "de-DE", "it" => "it-IT", "pt" => "pt-PT", _ => "en-US"
        };
        var culture = CultureInfo.GetCultureInfo(cultureName);
        CultureInfo.CurrentCulture = culture;
        CultureInfo.CurrentUICulture = culture;
    }
}

public sealed record LanguageOption(string Code, string Label, string Name);
